head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > hammerPressTime]<br/>hammerEnabled=true 일때 oncelldblclick 이벤트가 발생하기까지 누르고 있어야 할 시간을 밀리초(ms)로 설정합니다.",
    "validation" : [
        "Number 값으로 oncelldblclick 이벤트가 발생하기까지 Long Press 액션을 유지해야 하는 시간을 밀리초(ms)로 설정합니다.",
        "속성값을 설정하지 않으면 351 이 적용됩니다.",
        "hammerEnabled=true 인 환경에서 동작하며, 모바일 환경이 아니거나 dataDragDrop, dataDragDropSelf, dataDragDropOther, dataDragDropCell 속성이 모두 false 가 아니면 동작하지 않습니다. (본 샘플은 hammerEnabled=true 고정 + dataDragDrop 계열 속성을 모두 미설정 상태로 고정)",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 item select1 은 selectedIndex 초기 미적용 → 기본 선택을 미설정(빈값)으로 지정
    con_hammerPressTime.setValue('');

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con_hammerPressTime : 셀렉트박스 선택값 (빈값이면 속성 미부여 → 엔진 기본 351 적용)
    //  - 값 전달 시 getText 아닌 getValue 사용
    let vPressTimeRaw = con_hammerPressTime.getValue();
    let vPressTime = (vPressTimeRaw === null || vPressTimeRaw === undefined) ? '' : String(vPressTimeRaw).trim();

    // 사용법 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  전제(동작 조건) : hammerEnabled=true 이고 (a) 모바일/터치 환경이며 (b) dataDragDrop, dataDragDropSelf, dataDragDropOther, dataDragDropCell 이 모두 false(미설정) 여야 함.
    //  하나라도 위배되면(비모바일이거나 dataDragDrop 계열 중 하나라도 true 면) 동작하지 않는다. → 본 샘플은 hammerEnabled=true 고정 + dataDragDrop 계열 속성을 일절 설정하지 않음.
    //  hammerEnabled=true + 모바일/터치 환경에서 Cell 을 hammerPressTime(ms) 만큼 Long Press 하면 oncelldblclick 이벤트가 발생.
    $c.gcm.createLabel('label="전제 : hammerEnabled=true 고정 + (a) 모바일/터치 환경 + (b) dataDragDrop/dataDragDropSelf/dataDragDropOther/dataDragDropCell 모두 미설정(false) 일 때만 동작(본 샘플 고정). con_hammerPressTime = ' + (vPressTime === '' ? '미설정(기본 351ms 적용)' : vPressTime + 'ms') + '. 모바일/터치 환경에서 Cell 을 해당 시간(ms)만큼 Long Press 하면 oncelldblclick 이벤트가 발생. 데스크탑(비터치)에서는 동작하지 않음."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성 (col1=text, col2=number, col3=text, col4=number)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="number"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 데이터 4행 로드
    let jsonData = [
        { "col1": "행1", "col2": 100, "col3": "Aa", "col4": 10 },
        { "col1": "행2", "col2": 200, "col3": "Bb", "col4": 20 },
        { "col1": "행3", "col2": 300, "col3": "Cc", "col4": 30 },
        { "col1": "행4", "col2": 400, "col3": "Dd", "col4": 40 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정 (createCList 공통 함수)
    //  - hammerEnabled : true 고정 (hammerPressTime 동작 전제)
    //  - hammerPressTime : con 입력값 (빈값이면 속성 미부여 → 엔진 기본 351 적용)
    //  - dataDragDrop 계열 속성은 전제에 따라 일절 설정하지 않음(모두 미설정 = false 유지)
    let properties = {
        dataList: "data:dlt_bind",
        hammerEnabled: true,
    };
    if (vPressTime !== '') {
        properties.hammerPressTime = Number(vPressTime);
    }
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';

    // target 생성 (Body 4컬럼, 단일 Row 헤더).
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:700px;height:160px;" ev:oncelldblclick="scwin.target1_oncelldblclick">';
    strTarget += '<w2:caption style="" id="caption1" value="hammerPressTime 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="170" style="" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" id="hcol2" value="col2"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="170" style="" inputType="text" dataType="text" id="col1" dataList="col1" editType="text"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" dataType="number" id="col2" dataList="col2" editType="text"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" dataType="text" id="col3" dataList="col3" editType="text"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" dataType="number" id="col4" dataList="col4" editType="text"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // hammerPressTime 적용값 출력
    //  - con 에 값을 입력하지 않으면 속성을 부여하지 않으므로 엔진 기본값(351)이 options.hammerPressTime 에 적용됨
    //  - con 에 숫자를 입력하면 그 값이 options.hammerPressTime 에 반영됨
    let applied = scwin.target1.options.hammerPressTime;
    let isDefault = (vPressTime === '');
    wf_body_bottom.getObj("scwin").setReturnValue("hammerPressTime 적용값(options.hammerPressTime) : " + applied + " ms" + (isDefault ? " (미설정 → 엔진 기본값 351 적용)" : " (입력값 반영)"));
}



// oncelldblclick : hammerEnabled=true 모바일/터치 환경에서 Cell 을 hammerPressTime(ms) 만큼 Long Press 하면 발생
//  - hammerPressTime 으로 설정한 시간만큼 누르고 있어야 본 핸들러가 호출됨을 확인(시간 입증용 출력)
scwin.target1_oncelldblclick = function (rowIndex, colIndex, value) {
    let b = wf_body_bottom.getObj("scwin");
    b.setReturnValue("oncelldblclick 발생 (Long Press " + scwin.target1.options.hammerPressTime + "ms 후) rowIndex : " + rowIndex + ", colIndex : " + colIndex + ", value : " + value);
};
